import { connect } from 'cloudflare:sockets';
const KV_KEY = 'config';
function getEnv(env) { const D = { PW: 'abc123456', AS: 'snip-sync-2024', SB: '' }; return { PW: env.PW || D.PW, AS: env.AS || D.AS, SB: env.SB || D.SB }; }
export default { async fetch(request, env, ctx) { const E = getEnv(env); try { const url = new URL(request.url); const authed = await isAuth(request, E); if (request.method === 'POST') { if (url.pathname === '/api/login') return await hLogin(request, E); if (url.pathname === '/api/logout') return hLogout(); if (url.pathname === '/api/config') return authed ? await sCfg(request, env) : nAuth(); } if (request.method === 'GET') { if (url.pathname === '/') { return new Response(authed ? gHTML(E) : gLogin(), { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8' } }); } if (url.pathname === '/api/config') return authed ? await gCfg(env) : nAuth(); if (url.pathname === '/api/sync') return await gSync(request, env, E); if (url.pathname === '/api/sync-share') return await gSyncShare(request, env, E); if (url.pathname === '/api/share') return await gShare(request, env, E); if (url.pathname === '/api/socks') return await gSocks(request, env, E); if (url.pathname === '/api/check-socks') return authed ? await hCS(request, env) : nAuth(); if (url.pathname === '/api/upstream') return authed ? await gUpApi(request, env) : nAuth(); if (/^\/[0-9a-f]{8}\/?$/i.test(url.pathname)) return await hSub(request, env, E); } if (request.method === 'OPTIONS') return new Response(null, { headers: cors() }); return new Response('Not Found', { status: 404 }); } catch (err) { return new Response(err.toString(), { status: 500 }); } } };
async function gSocks(request, env, E) { try { const ua = request.headers.get('User-Agent'); if (ua !== 'VLESS-Worker') { return new Response(JSON.stringify({ error: 'Forbidden' }), { status: 403, headers: { 'Content-Type': 'application/json', ...cors() } }); } const url = new URL(request.url); const key = url.searchParams.get('key') || request.headers.get('X-API-Key'); if (key !== E.AS) { return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { 'Content-Type': 'application/json', ...cors() } }); } const idx = parseInt(url.searchParams.get('index')); if (isNaN(idx) || idx < 0) { return new Response(JSON.stringify({ error: 'Invalid index' }), { status: 400, headers: { 'Content-Type': 'application/json', ...cors() } }); } if (idx >= SH_BASE) { const up = await gUp(env), it = up.list[idx - SH_BASE], c = it ? await gUpCfg(env, idx - SH_BASE) : null; if (!c) { return new Response(JSON.stringify({ error: 'shared SOCKS not available' }), { status: 404, headers: { 'Content-Type': 'application/json', ...cors() } }); } return new Response(JSON.stringify({ config: c, region: it.region, note: it.note }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); if (!data || !data.socks || idx >= data.socks.length) { return new Response(JSON.stringify({ error: 'SOCKS not found' }), { status: 404, headers: { 'Content-Type': 'application/json', ...cors() } }); } if (data.socks[idx].disabled) { return new Response(JSON.stringify({ error: 'SOCKS disabled' }), { status: 404, headers: { 'Content-Type': 'application/json', ...cors() } }); } return new Response(JSON.stringify({ config: data.socks[idx].config, region: data.socks[idx].region, note: data.socks[idx].note }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
function cors() { return { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type' }; }
function nrmSnips(cfg) { let a = Array.isArray(cfg.snippets) ? cfg.snippets : null; if (!a) { const o = cfg.snippet; a = (o && (o.domain || o.uuid)) ? [{ name: '', domain: o.domain || '', uuid: o.uuid || '', base: o.base !== false }] : []; } return a.filter(s => s && typeof s === 'object').map(s => ({ name: String(s.name || '').trim(), domain: String(s.domain || '').trim(), uuid: String(s.uuid || '').trim(), base: s.base !== false })); }
async function gCfg(env) { try { const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); const cfg = data || { socks: [], domains: [] }; cfg.snippets = nrmSnips(cfg); delete cfg.snippet; if (!cfg.share) cfg.share = { enabled: false, url: '' }; return new Response(JSON.stringify(cfg), { headers: { 'Content-Type': 'application/json; charset=utf-8', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
const SH_BASE = 1000, SH_TTL = 60000, SH_RTTL = 3600000;
let shC = null, shT = 0; const rlC = new Map();
function pShare(u) { try { const x = new URL(String(u).trim()); return { origin: x.origin, key: x.searchParams.get('key') || '' }; } catch (e) { return { origin: '', key: '' }; } }
async function gUp(env) { const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }) || {}, sh = data.share || {}; if (!sh.enabled || !sh.url) return { origin: '', key: '', list: [], error: '' }; const p = pShare(sh.url); if (!p.origin || !p.key) return { origin: '', key: '', list: [], error: '分享链接格式不对（应形如 https://xxx/api/share?key=yyy）' }; const now = Date.now(); if (shC && shC.origin === p.origin && shC.key === p.key && now - shT < SH_TTL) return shC; try { const r = await fetch(`${p.origin}/api/sync-share?key=${encodeURIComponent(p.key)}`, { headers: { 'User-Agent': 'VLESS-Worker' } }); if (!r.ok) throw new Error('上游返回 HTTP ' + r.status); const d = await r.json(); if (d && d.error) throw new Error(d.error); const list = (Array.isArray(d && d.socks) ? d.socks : []).filter(s => s && !s.disabled).map((s, i) => ({ region: s.region || '', note: s.note || '', up: (s.idx !== undefined ? s.idx : i), config: String(s.config || '').trim(), relay: typeof s.relay === 'string' ? s.relay : '' })).filter(s => s.config || s.relay); shC = { origin: p.origin, key: p.key, list, error: '' }; shT = now; return shC; } catch (e) { if (shC && shC.origin === p.origin) return { ...shC, error: e.message }; return { origin: p.origin, key: p.key, list: [], error: e.message }; } }
async function gUpCfg(env, m) { const up = await gUp(env), it = up.list[m]; if (!it) return null; if (it.config) return it.config; if (!it.relay || !up.origin) return null; const k = up.origin + '|' + it.relay, now = Date.now(), c = rlC.get(k); if (c && now - c.t < SH_RTTL) return c.v; try { const r = await fetch(`${up.origin}/api/socks-relay?token=${encodeURIComponent(it.relay)}`, { headers: { 'User-Agent': 'VLESS-Worker' } }); if (!r.ok) return null; const d = await r.json(), v = String((d && d.config) || '').trim(); if (!v) return null; rlC.set(k, { v, t: now }); return v; } catch (e) { return null; } }
async function gUpApi(request, env) { const up = await gUp(env), data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }) || {}, sh = data.share || {}; return new Response(JSON.stringify({ enabled: !!sh.enabled, url: sh.url || '', origin: up.origin, error: up.error || '', socks: up.list.map((s, m) => ({ region: s.region, note: s.note, idx: SH_BASE + m, mode: s.config ? '明文' : '中转' })) }), { headers: { 'Content-Type': 'application/json; charset=utf-8', ...cors() } }); }
async function gSync(request, env, E) { try { const url = new URL(request.url); const key = url.searchParams.get('key') || request.headers.get('X-API-Key'); if (key !== E.AS) { return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { 'Content-Type': 'application/json', ...cors() } }); } const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); const cfg = data || { socks: [], domains: [] }; const filtered = { socks: (cfg.socks || []).map((s, i) => ({ ...s, idx: i })).filter(s => !s.disabled), domains: (cfg.domains || []).filter(d => !d.disabled) }; return new Response(JSON.stringify(filtered), { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store, max-age=0', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
async function gSyncShare(request, env, E) { try { const ua = request.headers.get('User-Agent'); if (ua !== 'VLESS-Worker') { return new Response(JSON.stringify({ error: 'Forbidden' }), { status: 403, headers: { 'Content-Type': 'application/json', ...cors() } }); } const url = new URL(request.url); const key = url.searchParams.get('key') || request.headers.get('X-API-Key'); if (key !== E.AS) { return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { 'Content-Type': 'application/json', ...cors() } }); } const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); const cfg = data || { socks: [], domains: [] }; const filtered = { socks: (cfg.socks || []).map((s, i) => ({ ...s, idx: i })).filter(s => !s.disabled), domains: (cfg.domains || []).filter(d => !d.disabled) }; return new Response(JSON.stringify(filtered), { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store, max-age=0', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
async function gShare(request, env, E) { try { const url = new URL(request.url); const key = url.searchParams.get('key') || request.headers.get('X-API-Key'); if (key !== E.AS) { return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { 'Content-Type': 'application/json', ...cors() } }); } const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); const cfg = data || { socks: [], domains: [] }; const enabledSocks = (cfg.socks || []).map((s, i) => ({ ...s, idx: i })).filter(s => !s.disabled); const enabledDomains = (cfg.domains || []).filter(d => !d.disabled); const masked = { socks: enabledSocks.map(s => ({ region: s.region, config: `socks${s.idx}`, note: s.note, idx: s.idx })), domains: enabledDomains }; return new Response(JSON.stringify(masked), { headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store, max-age=0', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
async function sCfg(request, env) { try { const body = await request.json(); const old = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }) || {}; const cfg = { ...old }; if (Array.isArray(body.socks)) cfg.socks = body.socks; if (Array.isArray(body.domains)) cfg.domains = body.domains; if (Array.isArray(body.snippets)) { cfg.snippets = nrmSnips({ snippets: body.snippets }); delete cfg.snippet; } else if (body.snippet && typeof body.snippet === 'object') { cfg.snippets = nrmSnips({ snippet: body.snippet }); delete cfg.snippet; } if (body.share && typeof body.share === 'object') cfg.share = { enabled: !!body.share.enabled, url: String(body.share.url || '').trim() }; if (!Array.isArray(cfg.socks)) cfg.socks = []; if (!Array.isArray(cfg.domains)) cfg.domains = []; await env.CONFIG_KV.put(KV_KEY, JSON.stringify(cfg)); shC = null; shT = 0; return new Response(JSON.stringify({ success: true }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors() } }); } }
function pS5(s) { if (!s) return null; s = s.trim(); let u = '', p = '', h, pt; const ai = s.lastIndexOf('@'); if (ai > 0) { const ap = s.substring(0, ai), hp = s.substring(ai + 1); const ci = ap.indexOf(':'); if (ci > 0) { u = ap.substring(0, ci); p = ap.substring(ci + 1); } const lc = hp.lastIndexOf(':'); if (lc > 0) { h = hp.substring(0, lc); pt = Number(hp.substring(lc + 1)); } else { h = hp; pt = 1080; } } else { const lc = s.lastIndexOf(':'); if (lc > 0) { h = s.substring(0, lc); pt = Number(s.substring(lc + 1)); } else { h = s; pt = 1080; } } if (isNaN(pt) || pt <= 0 || pt > 65535) return null; return { username: u, password: p, hostname: h, port: pt }; }
async function c2s5(pC, tH, tP) { const { username, password, hostname, port } = pC; const socket = connect({ hostname, port }); const writer = socket.writable.getWriter(); const reader = socket.readable.getReader(); try { const authMethods = username ? new Uint8Array([5, 2, 0, 2]) : new Uint8Array([5, 1, 0]); await writer.write(authMethods); const res1 = await reader.read(); if (res1.done || res1.value.byteLength < 2) throw new Error('握手失败'); const methodRes = new Uint8Array(res1.value); if (methodRes[0] !== 5 || methodRes[1] === 255) throw new Error('不支持的认证方式'); if (methodRes[1] === 2) { if (!username || !password) throw new Error('需要认证'); const enc = new TextEncoder(); const uBytes = enc.encode(username), pBytes = enc.encode(password); const authReq = new Uint8Array([1, uBytes.length, ...uBytes, pBytes.length, ...pBytes]); await writer.write(authReq); const res2 = await reader.read(); if (res2.done || new Uint8Array(res2.value)[1] !== 0) throw new Error('认证失败'); } const hostBytes = new TextEncoder().encode(tH); const connReq = new Uint8Array([5, 1, 0, 3, hostBytes.length, ...hostBytes, tP >> 8, tP & 255]); await writer.write(connReq); const res3 = await reader.read(); if (res3.done || new Uint8Array(res3.value)[1] !== 0) throw new Error('连接目标失败'); writer.releaseLock(); reader.releaseLock(); return socket; } catch (e) { writer.releaseLock(); reader.releaseLock(); try { socket.close(); } catch (x) { } throw e; } }
async function hCS(request, env) { const url = new URL(request.url); const cfg = url.searchParams.get('config'); const idx = url.searchParams.get('index'); let socksConfig = cfg; let isDisabled = false; if (idx !== null && !cfg) { const i = parseInt(idx); if (i >= SH_BASE) { socksConfig = await gUpCfg(env, i - SH_BASE); } else { const data = await env.CONFIG_KV.get(KV_KEY, { type: 'json' }); if (data && data.socks && i >= 0 && i < data.socks.length) { socksConfig = data.socks[i].config; isDisabled = data.socks[i].disabled; } } } if (isDisabled) { return new Response(JSON.stringify({ status: 'disabled', error: '已禁用', latency: -1 }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } if (!socksConfig) { return new Response(JSON.stringify({ status: 'error', error: '无效配置' }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } const startTime = Date.now(); try { const parsed = pS5(socksConfig); if (!parsed) { return new Response(JSON.stringify({ status: 'offline', error: '配置格式错误', latency: -1 }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } const timeoutPromise = new Promise((_, rej) => setTimeout(() => rej(new Error('连接超时')), 3000)); const connPromise = c2s5(parsed, '1.1.1.1', 80); const socket = await Promise.race([connPromise, timeoutPromise]); const latency = Date.now() - startTime; try { socket.close(); } catch (e) { } return new Response(JSON.stringify({ status: 'online', latency }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } catch (e) { return new Response(JSON.stringify({ status: 'offline', error: e.message || '连接失败', latency: -1 }), { headers: { 'Content-Type': 'application/json', ...cors() } }); } }
function nAuth() { return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { 'Content-Type': 'application/json', ...cors() } }); }
const TK_TTL = 7 * 24 * 3600 * 1000;
async function hmac(secret, msg) { const enc = new TextEncoder(), k = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']), s = await crypto.subtle.sign('HMAC', k, enc.encode(msg)); return btoa(String.fromCharCode(...new Uint8Array(s))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
async function mkTk(E) { const exp = String(Date.now() + TK_TTL); return exp + '.' + await hmac(E.PW + E.AS, exp); }
async function vTk(tk, E) { const i = tk ? tk.indexOf('.') : -1; if (i <= 0) return false; const exp = tk.slice(0, i), sig = tk.slice(i + 1); if (!/^\d+$/.test(exp) || Number(exp) < Date.now()) return false; return sig === await hmac(E.PW + E.AS, exp); }
