async function hLogin(request, E) { let pw = ''; try { pw = (await request.json()).pw || ''; } catch (e) { } if (!E.PW || pw !== E.PW) return new Response(JSON.stringify({ error: '密码错误' }), { status: 401, headers: { 'Content-Type': 'application/json' } }); return new Response(JSON.stringify({ success: true }), { headers: { 'Content-Type': 'application/json', 'Set-Cookie': `mtk=${await mkTk(E)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${TK_TTL / 1000}` } }); }
function hLogout() { return new Response(JSON.stringify({ success: true }), { headers: { 'Content-Type': 'application/json', 'Set-Cookie': 'mtk=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0' } }); }
function isVF(uuid) { return /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(uuid); }
function genSocksKey(uuid, idx) { const src = uuid + '-socks-' + idx, chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789'; let hash = 0; for (let i = 0; i < src.length; i++) { hash = ((hash << 5) - hash) + src.charCodeAt(i); hash = hash & hash; } let key = ''; for (let i = 0; i < 8; i++) { hash = Math.abs((hash * 1103515245 + 12345) & 0x7fffffff); key += chars[hash % chars.length]; } return key; }
function gLinks(sc, dl, uuid, wd, base) { const p = 443, links = [], wp = '/?ed=2048', sfxOn = dl.length > 1, mk = (dm, path, name) => { const pm = new URLSearchParams({ encryption: 'none', security: 'tls', type: 'ws', host: wd, path }); pm.append('sni', wd); pm.append('fp', 'firefox'); links.push(`vless://${uuid}@${dm}:${p}?${pm.toString()}#${encodeURIComponent(name)}`); }; dl.forEach((item, di) => { const sfx = sfxOn ? '-D' + (di + 1) : ''; if (base || sc.length === 0) mk(item.domain, wp, `Snip-默认${sfx}`); sc.forEach(s => { const sp = `/?ed=2048&socks=${s.idx}&${genSocksKey(uuid, s.idx)}`, nm = `Snip-${s.region || 'socks' + s.idx}${s.note ? '-' + s.note : ''}`; mk(item.domain, sp, `${nm}-全局${sfx}`); mk(item.domain, sp + '&fb', `${nm}-回落${sfx}`); }); }); return links; }
function gN(sc, dl, uuid, wd, base) { const nodes = [], seen = {}, uniq = t => { if (seen[t] === undefined) { seen[t] = 0; return t; } seen[t]++; return `${t}·${seen[t]}`; }, mkN = (tag, domain, path) => ({ type: 'vless', tag, server: domain, server_port: 443, uuid, tls: { enabled: true, server_name: wd, utls: { enabled: true, fingerprint: 'firefox' } }, transport: { type: 'ws', path, headers: { Host: wd } } }), sfxOn = dl.length > 1; dl.forEach((item, di) => { const sfx = sfxOn ? '-D' + (di + 1) : ''; if (base || sc.length === 0) nodes.push(mkN(uniq(`Snip-默认${sfx}`), item.domain, '/?ed=2048')); sc.forEach(s => { const sp = `/?ed=2048&socks=${s.idx}&${genSocksKey(uuid, s.idx)}`, nm = `Snip-${s.region || 'socks' + s.idx}${s.note ? '-' + s.note : ''}`; nodes.push(mkN(uniq(`${nm}-全局${sfx}`), item.domain, sp)); nodes.push(mkN(uniq(`${nm}-回落${sfx}`), item.domain, sp + '&fb')); }); }); if (nodes.length === 0) return null; const tags = nodes.map(n => n.tag), sel = '🚀 节点选择', auto = '♻️ 自动选择'; return { log: { level: 'warn' }, dns: { servers: [{ type: 'udp', tag: 'dns-direct', server: '223.5.5.5' }], final: 'dns-direct' }, inbounds: [{ type: 'mixed', tag: 'mixed-in', listen: '127.0.0.1', listen_port: 2080 }, { type: 'tun', tag: 'tun-in', address: ['172.18.0.1/30'], auto_route: true, strict_route: true, stack: 'mixed' }], outbounds: [{ type: 'selector', tag: sel, outbounds: [auto, ...tags], default: auto }, { type: 'urltest', tag: auto, outbounds: tags, url: 'https://www.gstatic.com/generate_204', interval: '3m' }, ...nodes, { type: 'direct', tag: 'direct' }], route: { rules: [{ action: 'sniff' }, { protocol: 'dns', action: 'hijack-dns' }, { ip_is_private: true, action: 'route', outbound: 'direct' }], final: sel, auto_detect_interface: true, default_domain_resolver: 'dns-direct' } }; }
